using System.Text.RegularExpressions;
using KiriChess.Engine.Config;
using KiriChess.Engine.Core;

namespace KiriChess.Engine.Tests.Generative;

/// <summary>
/// SAN is generated by Gera.Chess and consumed by <c>PgnBuilder</c> and the UI's move list, and
/// nothing in this repo parses PGN back - so <see cref="SanTests"/>'s eight examples were the entire
/// guard on a string that leaves the building. This file is the property test behind those examples:
/// SAN identifies exactly one legal move, matches the grammar of standard algebraic notation, and
/// agrees with KiriChess's own check/mate reads.
///
/// <para>The grammar deliberately excludes <c>$</c>. Gera.Chess appends that to a stalemating move;
/// standard SAN has no stalemate suffix, and in PGN movetext a bare <c>$</c> begins a NAG, so
/// <c>Qg6$</c> made every stalemated game's export unparseable. <see cref="KiriChessEngine"/> now
/// strips it; this is the property that keeps it stripped.</para>
///
/// <para><b>Budget.</b> Uniqueness requires applying every legal move in a position, so it is sampled
/// every 15th ply rather than every ply. Two games per pool on a default run is enough to hit
/// promotions, checks and the occasional stalemate without eating the shared 25s budget; soak
/// multiplies that via <see cref="GenerativeBudget"/>.</para>
/// </summary>
public sealed class SanInvariantTests
{
    private static readonly Regex Grammar = new(
        @"^(O-O(-O)?|[KQRBN]?[a-h]?[1-8]?x?[a-h][1-8](=[QRBN])?)[+#]?$",
        RegexOptions.Compiled | RegexOptions.CultureInvariant);

    public static IEnumerable<object[]> Pools => SelfPlay.PoolKeys.Select(k => new object[] { k });

    private const int GamesPerPool = 2;

    [Theory]
    [MemberData(nameof(Pools))]
    public void San_is_standard_unique_and_agrees_with_check_and_mate(string poolKey)
    {
        var engine = new KiriChessEngine();
        var config = SelfPlay.ConfigFor(poolKey);
        var ledger = new InvariantLedger();
        var games = GenerativeBudget.Games(GamesPerPool);

        for (var g = 0; g < games; g++)
        {
            var seed = SelfPlay.SeedFor(poolKey, g);
            SelfPlay.Walk(engine, config, poolKey, seed, ply => CheckPly(engine, ply, ledger));
        }

        ledger.AssertClean($"SanInvariants[{poolKey}]");
    }

    private static void CheckPly(KiriChessEngine engine, Ply ply, InvariantLedger ledger)
    {
        var san = ply.Result.San;

        if (Grammar.IsMatch(san) && !san.Contains('$')) ledger.Checked();
        else ledger.Violation("SanGrammar", ply, $"san='{san}' is not standard algebraic notation.");

        if ((san.EndsWith('#') ? 1 : 0) == (ply.Result.Status == GameStatus.Checkmate ? 1 : 0))
            ledger.Checked();
        else
            ledger.Violation("HashIffCheckmate", ply, $"san='{san}' status={ply.Result.Status}.");

        if (ply.Config.CheckCheckerGain > 0)
        {
            var chip = ply.Result.Events.Any(e => e.Type == ClockEventType.CheckGain);
            if ((san.EndsWith('+') ? 1 : 0) == (chip ? 1 : 0)) ledger.Checked();
            else ledger.Violation("PlusIffCheckChip", ply, $"san='{san}' check-chip={chip}.");
        }

        if (ply.Index % 15 != 0) return;

        var seen = new Dictionary<string, string>(StringComparer.Ordinal);
        foreach (var move in ply.Legal)
        {
            var probe = engine.Apply(ply.Before, move, ply.Config, thinkTimeSeconds: 0);
            if (seen.TryGetValue(probe.San, out var other) && other != move.ToString())
                ledger.Violation("SanUniqueness", ply, $"san='{probe.San}' is produced by both {other} and {move}.");
            else
            {
                seen[probe.San] = move.ToString();
                ledger.Checked();
            }
        }
    }
}
